package com.yuegang.zhihui.inventory.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.inventory.application.*;import com.yuegang.zhihui.inventory.security.*;import jakarta.servlet.http.*;import jakarta.validation.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/v1/inventory")public final class InventoryReturnController{private final InventoryReturnService service;private final InventoryInternalSecurity security;public InventoryReturnController(InventoryReturnService s,InventoryInternalSecurity x){service=s;security=x;}@PostMapping("/return-sold")ApiResponse<InventoryView>returned(@Valid @RequestBody InventoryCommand b,HttpServletRequest r){security.verify(r);return ApiResponse.success(service.returnSold(b),TraceIdResolver.resolve(r));}}
